// Packs build-web/lsfgprep.js + lsfgprep.wasm into wasm/lsfgprep-bundle.js (one <script>): the page then works
// opened straight from disk (file://), where browsers refuse to load workers and fetch local files.
'use strict';
const fs = require('fs'), path = require('path');
const [, , dir, out] = process.argv;
const js = fs.readFileSync(path.join(dir, 'lsfgprep.js'), 'utf8');
const wasm = fs.readFileSync(path.join(dir, 'lsfgprep.wasm')).toString('base64');
fs.writeFileSync(out, '// generated by wasm-src/make-bundle.js\nself.LSFGPREP={js:' + JSON.stringify(js) + ',wasm:"' + wasm + '"};\n');
console.log('bundle', out, fs.statSync(out).size, 'bytes');
